{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FACT_PARETO_TARGET_PERFORMANCE_MASTER AS WITH FY_MONTHS_GENERATOR AS ( SELECT SEQ.SEQ AS MONTH_OFFSET, TO_CHAR(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'YYYY-MM\') AS REPORT_MONTH, TO_CHAR(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'Mon YYYY\') AS MONTH_LABEL, DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())) AS START_DATE, CASE WHEN SEQ.SEQ = 0 THEN CURRENT_DATE() ELSE LAST_DAY(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE()))) END AS END_DATE, DATEADD(\'DAY\', -29, CASE WHEN SEQ.SEQ = 0 THEN CURRENT_DATE() ELSE LAST_DAY(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE()))) END) AS START_DATE_30, DATEADD(\'DAY\', -59, CASE WHEN SEQ.SEQ = 0 THEN CURRENT_DATE() ELSE LAST_DAY(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE()))) END) AS START_DATE_60, DATEADD(\'DAY\', -89, CASE WHEN SEQ.SEQ = 0 THEN CURRENT_DATE() ELSE LAST_DAY(DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE()))) END) AS START_DATE_90, \'2026-04-01\'::DATE AS FY_START_DATE FROM ( SELECT ROW_NUMBER() OVER (ORDER BY NULL) - 1 AS SEQ FROM TABLE(GENERATOR(ROWCOUNT => 12)) ) SEQ WHERE DATEADD(\'MONTH\', -SEQ.SEQ, DATE_TRUNC(\'MONTH\', CURRENT_DATE())) >= \'2026-04-01\'::DATE ), LATEST_INV_DATES AS ( SELECT P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, P.START_DATE_30, P.START_DATE_60, P.START_DATE_90, P.FY_START_DATE, COALESCE(MAX(I.DATE), P.END_DATE) AS MAX_INV_DATE, MAX(CASE WHEN P.START_DATE = P.FY_START_DATE AND I.DATE <= DATEADD(\'DAY\', 1, P.FY_START_DATE) THEN I.DATE WHEN P.START_DATE <> P.FY_START_DATE AND I.DATE <= P.START_DATE THEN I.DATE END) AS OPENING_DATE_CALENDAR, MAX(CASE WHEN P.START_DATE = P.FY_START_DATE AND I.DATE <= DATEADD(\'DAY\', 1, P.FY_START_DATE) THEN I.DATE WHEN P.START_DATE <> P.FY_START_DATE AND I.DATE <= P.START_DATE_30 THEN I.DATE END) AS OPENING_DATE_30, MAX(CASE WHEN I.DATE <= P.START_DATE_60 THEN I.DATE END) AS OPENING_DATE_60, MAX(CASE WHEN I.DATE <= P.START_DATE_90 THEN I.DATE END) AS OPENING_DATE_90 FROM FY_MONTHS_GENERATOR P LEFT JOIN SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I ON I.DATE >= \'2026-04-01\' AND I.DATE <= P.END_DATE GROUP BY P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, P.START_DATE_30, P.START_DATE_60, P.START_DATE_90, P.FY_START_DATE, P.MONTH_OFFSET ), STORE_ZONE_MAP_CLEAN AS ( SELECT CAST(BRANCH_CODE AS VARCHAR) AS BRANCH_CODE, MAX(STORE_NAME) AS STORE_NAME, MAX(CLUSTER_NAME) AS CLUSTER_NAME FROM SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP GROUP BY CAST(BRANCH_CODE AS VARCHAR) ), STORE_MONTHLY_TARGETS_RAW AS ( SELECT CAST(TRIM(BRANCH_CODE) AS VARCHAR) AS BRANCH_CODE, TO_CHAR( COALESCE( TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\') ), \'YYYY-MM\' ) AS REPORT_MONTH, AVG(TRY_CAST(REGEXP_REPLACE(TRIM(CUMULATIVE_TARGET_MTD), \'[^0-9.]\', \'\') AS NUMBER(18,2))) AS STORE_TARGET FROM SNITCH_DB.MAPLEMONK.MTD_TARGET_CLEAN WHERE TARGET_MONTH IS NOT NULL AND CUMULATIVE_TARGET_MTD IS NOT NULL AND REGEXP_REPLACE(TRIM(CUMULATIVE_TARGET_MTD), \'[^0-9.]\', \'\') <> \'\' AND COALESCE(TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\')) >= \'2026-04-01\' GROUP BY CAST(TRIM(BRANCH_CODE) AS VARCHAR), TO_CHAR(COALESCE(TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\')), \'YYYY-MM\') ), HIERARCHY_TARGETS AS ( SELECT \'3. Store Wise\' AS HIERARCHY_LEVEL, S.BRANCH_CODE AS LOCATION_ID, S.REPORT_MONTH, S.STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S UNION ALL SELECT \'2. Cluster Wise\' AS HIERARCHY_LEVEL, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS LOCATION_ID, S.REPORT_MONTH, SUM(S.STORE_TARGET) AS STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S LEFT JOIN STORE_ZONE_MAP_CLEAN M ON S.BRANCH_CODE = M.BRANCH_CODE GROUP BY COALESCE(M.CLUSTER_NAME, \'OTHERS\'), S.REPORT_MONTH UNION ALL SELECT \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, S.REPORT_MONTH, SUM(S.STORE_TARGET) AS STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S GROUP BY S.REPORT_MONTH ), BP_STYLE AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, MAX(NULLIF(UPPER(TRIM(L1_CATEGORY)), \'\')) AS L1_CATEGORY FROM SNITCH_DB.MAPLEMONK.BASE_PRODUCT GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), MF_NORMALIZED AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, COALESCE( CASE WHEN MF.CATEGORY IS NOT NULL AND TRIM(MF.CATEGORY) <> \'\' THEN CASE WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'T-SHIRTS\',\'T-SHIRT\',\'T SHIRTS\',\'T SHIRT\',\'TSHIRTS\',\'TSHIRT\',\'ROUND NECK\',\'ROUNDNECK\',\'POLO\',\'POLOS\',\'POLO T-SHIRT\',\'POLO T-SHIRTS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'TROUSER\',\'TROUSERS\',\'CHINO\',\'CHINOS\',\'CHINO TROUSER\',\'CHINO TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'JEAN\',\'JEANS\',\'DENIM\',\'DENIMS\',\'DEMIN\',\'DEMINS\') THEN \'JEANS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'JACKET\',\'JACKETS\') THEN \'JACKETS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SWEATER\',\'SWEATERS\') THEN \'SWEATERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'HOODIE\',\'HOODIES\') THEN \'HOODIES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'OVERSHIRT\',\'OVERSHIRTS\',\'OVER SHIRT\',\'OVER SHIRTS\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SHORT\',\'SHORTS\') THEN \'SHORTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SHIRT\',\'SHIRTS\',\'HALF SLEEVE SHIRT\',\'HALF SLEEVE SHIRTS\',\'HALF SLV SHIRT\',\'HALF SLV SHIRTS\',\'FULL SLEEVE SHIRT\',\'FULL SLEEVE SHIRTS\',\'FULL SLV SHIRT\',\'FULL SLV SHIRTS\') THEN \'SHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BLAZER\',\'BLAZERS\',\'SUIT\',\'SUITS\',\'SUITS & BLAZERS\') THEN \'BLAZERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'CARGO\',\'CARGOS\',\'CARGO PANT\',\'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SWEATSHIRT\',\'SWEATSHIRTS\',\'SWEAT SHIRT\',\'SWEAT SHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'COORD\',\'COORDS\',\'CO-ORD\',\'CO-ORDS\',\'CO ORD\',\'CO ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'JOGGER\',\'JOGGERS\',\'TRACKPANT\',\'TRACKPANTS\',\'TRACK PANT\',\'TRACK PANTS\',\'JOGGERS & TRACKPANTS\',\'JOGGERS AND TRACKPANTS\') THEN \'JOGGERS & TRACKPANTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BOXER\',\'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BAG\',\'BAGS\',\'BACKPACK\',\'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'INNERWEAR\',\'INNER WEAR\',\'BRIEF\',\'BRIEFS\',\'BREIF\',\'BREIFS\',\'TRUNK\',\'TRUNKS\') THEN \'INNERWEAR\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SHOE\',\'SHOES\',\'FOOTWEAR\',\'SNEAKER\',\'SNEAKERS\') THEN \'SHOES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'ACCESSORY\',\'ACCESSORIES\',\'SOCK\',\'SOCKS\',\'CAP\',\'CAPS\') THEN \'ACCESSORIES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SUNGLASS\',\'SUNGLASSES\',\'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BELT\',\'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'PERFUME\',\'PERFUMES\',\'FRAGRANCE\',\'FRAGRANCES\') THEN \'PERFUMES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'PYJAMA\',\'PYJAMAS\',\'PAJAMA\',\'PAJAMAS\') THEN \'PYJAMAS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'LUGGAGE\',\'TROLLY\',\'TROLLIES\',\'TROLLEY\',\'TROLLEYS\',\'SUITCASE\') THEN \'LUGGAGE\' ELSE UPPER(TRIM(MF.CATEGORY)) END END, CASE WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MST|4RN|4LRN|4BRN|4PL|4LPL|4BPL|RN|LRN|BRN|PL|LPL|BPL)\') THEN \'T-SHIRTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4TRU|4BR|TRU|BR)\') THEN \'INNERWEAR\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LSWT|4BSWT|4SWT|LSWT|BSWT|SWT)\') THEN \'SWEATSHIRTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4SHO|SHO|SH0)\') THEN \'SHOES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSR|4MTR|4MCN|4BCN|4TR|4LTR|4BTR|4CH|4LCH|4BCH|LTR|BTR|LCH|BCH|CH|TR)\') THEN \'TROUSERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MVK|4MSD|4MJN|4BJN|4JE|4LJE|4BJE|JE|LJE|BJE)\') THEN \'JEANS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LJK|4BJK|4JK|LJK|BJK|JK)\') THEN \'JACKETS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSW|4LSW|4BSW|4SW|LSW|BSW|SW)\') THEN \'SWEATERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LHD|4BHD|4HD|LHD|BHD|HD)\') THEN \'HOODIES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MOS|4LOS|4BOS|4OS|LOS|BOS|OS)\') THEN \'OVERSHIRT\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSS|4MSN|4SHS|4LSHS|4BSHS|4SFS|4LSFS|4BSFS|LSHS|BSHS|SHS|LSFS|BSFS|SFS)\') THEN \'SHIRTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4SH|4LSH|4BSH|LSH|BSH|SH)\') THEN \'SHORTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LBL|4BBL|4BL|LBL|BBL|BL)\') THEN \'BLAZERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MCG|4LCA|4BCA|4CA|LCA|BCA|CA)\') THEN \'CARGO PANTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MCD|4LCD|4BCD|4CD|LCD|BCD|CD)\') THEN \'COORDS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MTP|4LJO|4BJO|4JO|LJO|BJO|JO)\') THEN \'JOGGERS & TRACKPANTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4BX|BX)\') THEN \'BOXERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4BG|BG|BP)\') THEN \'BAGS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MCP|4MBD|4AC|AC)\') THEN \'ACCESSORIES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4SU|SU|SN)\') THEN \'SUNGLASSES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MBL|4BT|BT)\') THEN \'BELTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSFR|4PR|PR)\') THEN \'PERFUMES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4PY|PY)\') THEN \'PYJAMAS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MTL)\') THEN \'LUGGAGE\' ELSE \'OTHERS\' END ) AS CATEGORY, COALESCE( BP.L1_CATEGORY, CASE WHEN UPPER(MF.STYLE) LIKE \'%LUXE%\' OR UPPER(MF.SKU_GROUP) LIKE \'4MLX%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LRN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LPL%\' THEN \'LUXE\' WHEN UPPER(MF.STYLE) LIKE \'%PLUS%\' OR UPPER(MF.SKU_GROUP) LIKE \'4MBG%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BRN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BPL%\' THEN \'PLUS\' ELSE \'SNITCH\' END ) AS STYLE, NULLIF(UPPER(TRIM(MF.MATERIAL_NEW)), \'\') AS MATERIAL_NEW, NULLIF(UPPER(TRIM(MF.PRINT_DESIGN_MAPPED)), \'\') AS PRINT_DESIGN_MAPPED, NULLIF(UPPER(TRIM(MF.FIT)), \'\') AS FIT, NULLIF(UPPER(TRIM(MF.COLLAR_NEW)), \'\') AS COLLAR_NEW FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA MF LEFT JOIN BP_STYLE BP ON REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = BP.CLEAN_SKU_GROUP ), MF_SCORED AS ( SELECT *, ( IFF(CATEGORY IS NOT NULL AND CATEGORY <> \'OTHERS\', 1, 0) + IFF(STYLE IS NOT NULL AND STYLE <> \'\', 1, 0) + IFF(MATERIAL_NEW IS NOT NULL, 1, 0) + IFF(PRINT_DESIGN_MAPPED IS NOT NULL, 1, 0) + IFF(FIT IS NOT NULL, 1, 0) + IFF(COLLAR_NEW IS NOT NULL, 1, 0) ) AS META_COMPLETENESS_SCORE, ROW_NUMBER() OVER ( PARTITION BY CLEAN_SKU_GROUP ORDER BY ( IFF(CATEGORY IS NOT NULL AND CATEGORY <> \'OTHERS\', 1, 0) + IFF(STYLE IS NOT NULL AND STYLE <> \'\', 1, 0) + IFF(MATERIAL_NEW IS NOT NULL, 1, 0) + IFF(PRINT_DESIGN_MAPPED IS NOT NULL, 1, 0) + IFF(FIT IS NOT NULL, 1, 0) + IFF(COLLAR_NEW IS NOT NULL, 1, 0) ) DESC, CATEGORY ASC, STYLE ASC, MATERIAL_NEW ASC NULLS LAST, PRINT_DESIGN_MAPPED ASC NULLS LAST, FIT ASC NULLS LAST, COLLAR_NEW ASC NULLS LAST ) AS META_ROW_RANK FROM MF_NORMALIZED ), SKU_META_MASTER AS ( SELECT CLEAN_SKU_GROUP, CATEGORY, COALESCE(STYLE, \'SNITCH\') AS STYLE, CASE WHEN CATEGORY = \'T-SHIRTS\' THEN COALESCE(COLLAR_NEW, \'NA\') WHEN CATEGORY IN (\'SHIRTS\', \'JEANS\', \'TROUSERS\') THEN COALESCE(MATERIAL_NEW, \'NA\') ELSE \'NA\' END AS META1, CASE WHEN CATEGORY IN (\'T-SHIRTS\', \'SHIRTS\', \'JEANS\', \'TROUSERS\') THEN COALESCE(PRINT_DESIGN_MAPPED, \'NA\') ELSE \'NA\' END AS META2, CASE WHEN CATEGORY IN (\'T-SHIRTS\', \'SHIRTS\', \'JEANS\', \'TROUSERS\') THEN COALESCE(FIT, \'NA\') ELSE \'NA\' END AS META3 FROM MF_SCORED WHERE META_ROW_RANK = 1 ), SKU_LIVE_MRP AS ( SELECT REGEXP_REPLACE(UPPER(TRIM( CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END )), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, MAX(TRY_CAST(MRP AS FLOAT)) AS SKU_PRICE FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE TRY_CAST(MRP AS FLOAT) IS NOT NULL AND TRY_CAST(MRP AS FLOAT) > 0 GROUP BY 1 ), META_AVG_PRICES AS ( SELECT M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3, AVG(P.SKU_PRICE) AS META_DEFAULT_PRICE FROM SKU_META_MASTER M INNER JOIN SKU_LIVE_MRP P ON M.CLEAN_SKU_GROUP = P.CLEAN_SKU_GROUP GROUP BY M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3 ), CATEGORY_AVG_PRICES AS ( SELECT M.CATEGORY, AVG(P.SKU_PRICE) AS CAT_DEFAULT_PRICE FROM SKU_META_MASTER M INNER JOIN SKU_LIVE_MRP P ON M.CLEAN_SKU_GROUP = P.CLEAN_SKU_GROUP GROUP BY M.CATEGORY ), REF_SLABS_EXACT AS ( SELECT CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SLAB_MIN_PRICE, SLAB_MAX_PRICE FROM SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META QUALIFY ROW_NUMBER() OVER ( PARTITION BY CATEGORY, STYLE, META1, META2, META3, SLAB_MIN_PRICE ORDER BY PRICE_SLAB_CODE ASC ) = 1 ), REF_CATEGORY_BOUNDARIES AS ( SELECT DISTINCT CATEGORY, SLAB_MIN_PRICE FROM SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META UNION SELECT DISTINCT CATEGORY, BOUNDARY FROM SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META CROSS JOIN (SELECT COLUMN1 AS BOUNDARY FROM VALUES (0), (999), (1500), (2500)) ), REF_SLABS_CAT_RANGES AS ( SELECT CATEGORY, SLAB_MIN_PRICE, LEAD(SLAB_MIN_PRICE) OVER (PARTITION BY CATEGORY ORDER BY SLAB_MIN_PRICE) AS NEXT_SLAB_MIN_PRICE FROM REF_CATEGORY_BOUNDARIES ), REF_SLABS_CAT_ONLY AS ( SELECT CATEGORY, CONCAT(\'CAT_FALLBACK_\', CAST(SLAB_MIN_PRICE AS INT)) AS PRICE_SLAB_CODE, CASE WHEN NEXT_SLAB_MIN_PRICE IS NULL THEN CONCAT(\'₹\', CAST(SLAB_MIN_PRICE AS INT), \'+\') ELSE CONCAT(\'₹\', CAST(SLAB_MIN_PRICE AS INT), \' – ₹\', CAST(NEXT_SLAB_MIN_PRICE - 1 AS INT)) END AS PRICE_RANGE_LABEL, SLAB_MIN_PRICE, COALESCE(NEXT_SLAB_MIN_PRICE - 1, 999999) AS SLAB_MAX_PRICE FROM REF_SLABS_CAT_RANGES ), FALLBACK_BANDS AS ( SELECT COLUMN1 AS BAND_KEY, COLUMN2 AS BAND_MIN, COLUMN3 AS BAND_MAX_EXCLUSIVE FROM VALUES (\'VALUE\', 0, 999), (\'MID\', 999, 1500), (\'PREMIUM\', 1500, 2500), (\'SUPER_PREMIUM\', 2500, 999999) ), FALLBACK_STEPS AS ( SELECT ROW_NUMBER() OVER (ORDER BY NULL) - 1 AS STEP_IDX FROM TABLE(GENERATOR(ROWCOUNT => 500)) ), FALLBACK_PRICE_SLABS AS ( SELECT CONCAT(\'GLOBAL_\', B.BAND_KEY, \'_\', CAST(B.BAND_MIN + S.STEP_IDX * 200 AS INT)) AS PRICE_SLAB_CODE, CASE WHEN B.BAND_KEY = \'SUPER_PREMIUM\' AND S.STEP_IDX = 499 THEN CONCAT(\'₹\', CAST(B.BAND_MIN + S.STEP_IDX * 200 AS INT), \'+\') ELSE CONCAT( \'₹\', CAST(B.BAND_MIN + S.STEP_IDX * 200 AS INT), \' – ₹\', CAST(LEAST(B.BAND_MIN + S.STEP_IDX * 200 + 199, B.BAND_MAX_EXCLUSIVE - 1) AS INT) ) END AS PRICE_RANGE_LABEL, B.BAND_MIN + S.STEP_IDX * 200 AS SLAB_MIN_PRICE, CASE WHEN B.BAND_KEY = \'SUPER_PREMIUM\' AND S.STEP_IDX = 499 THEN 999999 ELSE LEAST(B.BAND_MIN + S.STEP_IDX * 200 + 199, B.BAND_MAX_EXCLUSIVE - 1) END AS SLAB_MAX_PRICE FROM FALLBACK_BANDS B CROSS JOIN FALLBACK_STEPS S WHERE B.BAND_MIN + S.STEP_IDX * 200 < B.BAND_MAX_EXCLUSIVE ), INV_SLABS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS CLUSTER_NAME, COALESCE( CASE WHEN UPPER(TRIM(META.CATEGORY)) NOT IN (\'NT\', \'CB\', \'OTHERS\', \'NA\', \'\') THEN META.CATEGORY ELSE NULL END, CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'T-SHIRTS\',\'T-SHIRT\',\'T SHIRTS\',\'T SHIRT\',\'TSHIRTS\',\'TSHIRT\',\'ROUND NECK\',\'ROUNDNECK\',\'POLO\',\'POLOS\',\'POLO T-SHIRT\',\'POLO T-SHIRTS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'TROUSER\',\'TROUSERS\',\'CHINO\',\'CHINOS\',\'CHINO TROUSER\',\'CHINO TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'JEAN\',\'JEANS\',\'DENIM\',\'DENIMS\',\'DEMIN\',\'DEMINS\') THEN \'JEANS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'JACKET\',\'JACKETS\') THEN \'JACKETS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SWEATER\',\'SWEATERS\') THEN \'SWEATERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'HOODIE\',\'HOODIES\') THEN \'HOODIES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'OVERSHIRT\',\'OVERSHIRTS\',\'OVER SHIRT\',\'OVER SHIRTS\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SHORT\',\'SHORTS\') THEN \'SHORTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SHIRT\',\'SHIRTS\',\'HALF SLEEVE SHIRT\',\'HALF SLEEVE SHIRTS\',\'HALF SLV SHIRT\',\'HALF SLV SHIRTS\',\'FULL SLEEVE SHIRT\',\'FULL SLEEVE SHIRTS\',\'FULL SLV SHIRT\',\'FULL SLV SHIRTS\') THEN \'SHIRTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BLAZER\',\'BLAZERS\',\'SUIT\',\'SUITS\',\'SUITS & BLAZERS\') THEN \'BLAZERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CARGO\',\'CARGOS\',\'CARGO PANT\',\'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SWEATSHIRT\',\'SWEATSHIRTS\',\'SWEAT SHIRT\',\'SWEAT SHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'COORD\',\'COORDS\',\'CO-ORD\',\'CO-ORDS\',\'CO ORD\',\'CO ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'JOGGER\',\'JOGGERS\',\'TRACKPANT\',\'TRACKPANTS\',\'TRACK PANT\',\'TRACK PANTS\',\'JOGGERS & TRACKPANTS\',\'JOGGERS AND TRACKPANTS\') THEN \'JOGGERS & TRACKPANTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BOXER\',\'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BAG\',\'BAGS\',\'BACKPACK\',\'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'INNERWEAR\',\'INNER WEAR\',\'BRIEF\',\'BRIEFS\',\'BREIF\',\'BREIFS\',\'TRUNK\',\'TRUNKS\') THEN \'INNERWEAR\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SHOE\',\'SHOES\',\'FOOTWEAR\',\'SNEAKER\',\'SNEAKERS\') THEN \'SHOES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'ACCESSORY\',\'ACCESSORIES\',\'SOCK\',\'SOCKS\',\'CAP\',\'CAPS\') THEN \'ACCESSORIES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'SUNGLASS\',\'SUNGLASSES\',\'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'BELT\',\'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'PERFUME\',\'PERFUMES\',\'FRAGRANCE\',\'FRAGRANCES\') THEN \'PERFUMES\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'PYJAMA\',\'PYJAMAS\',\'PAJAMA\',\'PAJAMAS\') THEN \'PYJAMAS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'LUGGAGE\',\'TROLLY\',\'TROLLIES\',\'TROLLEY\',\'TROLLEYS\',\'SUITCASE\') THEN \'LUGGAGE\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END ) AS CATEGORY, COALESCE(META.STYLE, \'SNITCH\') AS STYLE, COALESCE(META.META1, \'NA\') AS META1, COALESCE(META.META2, \'NA\') AS META2, COALESCE(META.META3, \'NA\') AS META3, COALESCE( R_EXACT.PRICE_SLAB_CODE, R_CAT.PRICE_SLAB_CODE, R_FALLBACK.PRICE_SLAB_CODE, CONCAT(\'SLAB_\', GREATEST(1, LEAST(10, FLOOR(COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) / 200) - 3))) ) AS PRICE_SLAB_CODE, COALESCE( R_EXACT.PRICE_RANGE_LABEL, R_CAT.PRICE_RANGE_LABEL, R_FALLBACK.PRICE_RANGE_LABEL, CONCAT(\'₹\', (FLOOR(COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) / 200) * 200), \' – ₹\', (FLOOR(COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) / 200) * 200) + 199) ) AS PRICE_RANGE_LABEL, COALESCE(I.INVENTORY, 0) AS INV_UNITS_CLOSING_INSTORE, COALESCE(I.JIT_QTY, 0) AS INV_UNITS_CLOSING_JIT, (COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_CLOSING FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.MAX_INV_DATE LEFT JOIN SKU_META_MASTER META ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = META.CLEAN_SKU_GROUP LEFT JOIN SKU_LIVE_MRP P ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = P.CLEAN_SKU_GROUP LEFT JOIN META_AVG_PRICES MA ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), MA.CATEGORY) AND EQUAL_NULL(COALESCE(META.STYLE, \'SNITCH\'), MA.STYLE) AND EQUAL_NULL(COALESCE(META.META1, \'NA\'), MA.META1) AND EQUAL_NULL(COALESCE(META.META2, \'NA\'), MA.META2) AND EQUAL_NULL(COALESCE(META.META3, \'NA\'), MA.META3) LEFT JOIN CATEGORY_AVG_PRICES CA ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), CA.CATEGORY) LEFT JOIN REF_SLABS_EXACT R_EXACT ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), R_EXACT.CATEGORY) AND EQUAL_NULL(COALESCE(META.STYLE, \'SNITCH\'), R_EXACT.STYLE) AND EQUAL_NULL(COALESCE(META.META1, \'NA\'), R_EXACT.META1) AND EQUAL_NULL(COALESCE(META.META2, \'NA\'), R_EXACT.META2) AND EQUAL_NULL(COALESCE(META.META3, \'NA\'), R_EXACT.META3) AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R_EXACT.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R_EXACT.SLAB_MAX_PRICE LEFT JOIN REF_SLABS_CAT_ONLY R_CAT ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), R_CAT.CATEGORY) AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R_CAT.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R_CAT.SLAB_MAX_PRICE LEFT JOIN FALLBACK_PRICE_SLABS R_FALLBACK ON COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R_FALLBACK.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R_FALLBACK.SLAB_MAX_PRICE LEFT JOIN STORE_ZONE_MAP_CLEAN M ON CAST(I.BRANCH_CODE AS VARCHAR) = M.BRANCH_CODE WHERE I.DATE >= \'2026-04-01\' AND CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') AND UPPER(TRIM(I.SKU_GROUP)) NOT LIKE \'CB%\' AND UPPER(TRIM(I.SKU_GROUP)) NOT LIKE \'NT%\' ), OPENING_INV_CALENDAR AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS CLUSTER_NAME, COALESCE( CASE WHEN UPPER(TRIM(META.CATEGORY)) NOT IN (\'NT\', \'CB\', \'OTHERS\', \'NA\', \'\') THEN META.CATEGORY ELSE NULL END, CASE REGEXP_REPLACE(UPPER(TRIM(I.NEW_CATEGORY)), \'[^A-Z0-9]\', \'\') WHEN \'TSHIRT\' THEN \'T-SHIRTS\' WHEN \'TSHIRTS\' THEN \'T-SHIRTS\' WHEN \'ROUNDNECK\' THEN \'T-SHIRTS\' WHEN \'POLO\' THEN \'T-SHIRTS\' WHEN \'POLOS\' THEN \'T-SHIRTS\' WHEN \'POLOTSHIRT\' THEN \'T-SHIRTS\' WHEN \'POLOTSHIRTS\' THEN \'T-SHIRTS\' WHEN \'TROUSER\' THEN \'TROUSERS\' WHEN \'TROUSERS\' THEN \'TROUSERS\' WHEN \'CHINO\' THEN \'TROUSERS\' WHEN \'CHINOS\' THEN \'TROUSERS\' WHEN \'CHINOTROUSER\' THEN \'TROUSERS\' WHEN \'CHINOTROUSERS\' THEN \'TROUSERS\' WHEN \'JEAN\' THEN \'JEANS\' WHEN \'JEANS\' THEN \'JEANS\' WHEN \'DENIM\' THEN \'JEANS\' WHEN \'DENIMS\' THEN \'JEANS\' WHEN \'JACKET\' THEN \'JACKETS\' WHEN \'JACKETS\' THEN \'JACKETS\' WHEN \'SWEATER\' THEN \'SWEATERS\' WHEN \'SWEATERS\' THEN \'SWEATERS\' WHEN \'HOODIE\' THEN \'HOODIES\' WHEN \'HOODIES\' THEN \'HOODIES\' WHEN \'OVERSHIRT\' THEN \'OVERSHIRT\' WHEN \'OVERSHIRTS\' THEN \'OVERSHIRT\' WHEN \'SHORT\' THEN \'SHORTS\' WHEN \'SHORTS\' THEN \'SHORTS\' WHEN \'SHIRT\' THEN \'SHIRTS\' WHEN \'SHIRTS\' THEN \'SHIRTS\' WHEN \'HALFSLEEVESHIRT\' THEN \'SHIRTS\' WHEN \'HALFSLEEVESHIRTS\' THEN \'SHIRTS\' WHEN \'HALFSLVSHIRT\' THEN \'SHIRTS\' WHEN \'HALFSLVSHIRTS\' THEN \'SHIRTS\' WHEN \'FULLSLEEVESHIRT\' THEN \'SHIRTS\' WHEN \'FULLSLEEVESHIRTS\' THEN \'SHIRTS\' WHEN \'FULLSLVSHIRT\' THEN \'SHIRTS\' WHEN \'FULLSLVSHIRTS\' THEN \'SHIRTS\' WHEN \'BLAZER\' THEN \'BLAZERS\' WHEN \'BLAZERS\' THEN \'BLAZERS\' WHEN \'SUIT\' THEN \'BLAZERS\' WHEN \'SUITS\' THEN \'BLAZERS\' WHEN \'SUITSBLAZERS\' THEN \'BLAZERS\' WHEN \'CARGO\' THEN \'CARGO PANTS\' WHEN \'CARGOS\' THEN \'CARGO PANTS\' WHEN \'CARGOPANT\' THEN \'CARGO PANTS\' WHEN \'CARGOPANTS\' THEN \'CARGO PANTS\' WHEN \'SWEATSHIRT\' THEN \'SWEATSHIRTS\' WHEN \'SWEATSHIRTS\' THEN \'SWEATSHIRTS\' WHEN \'COORD\' THEN \'COORDS\' WHEN \'COORDS\' THEN \'COORDS\' WHEN \'JOGGER\' THEN \'JOGGERS & TRACKPANTS\' WHEN \'JOGGERS\' THEN \'JOGGERS & TRACKPANTS\' WHEN \'TRACKPANT\' THEN \'JOGGERS & TRACKPANTS\' WHEN \'TRACKPANTS\' THEN \'JOGGERS & TRACKPANTS\' WHEN \'JOGGERSTRACKPANTS\' THEN \'JOGGERS & TRACKPANTS\' WHEN \'JOGGERSANDTRACKPANTS\' THEN \'JOGGERS & TRACKPANTS\' WHEN \'BOXER\' THEN \'BOXERS\' WHEN \'BOXERS\' THEN \'BOXERS\' WHEN \'BAG\' THEN \'BAGS\' WHEN \'BAGS\' THEN \'BAGS\' WHEN \'BACKPACK\' THEN \'BAGS\' WHEN \'BACKPACKS\' THEN \'BAGS\' WHEN \'INNERWEAR\' THEN \'INNERWEAR\' WHEN \'BRIEF\' THEN \'INNERWEAR\' WHEN \'BRIEFS\' THEN \'INNERWEAR\' WHEN \'BREIF\' THEN \'INNERWEAR\' WHEN \'BREIFS\' THEN \'INNERWEAR\' WHEN \'TRUNK\' THEN \'INNERWEAR\' WHEN \'TRUNKS\' THEN \'INNERWEAR\' WHEN \'SHOE\' THEN \'SHOES\' WHEN \'SHOES\' THEN \'SHOES\' WHEN \'FOOTWEAR\' THEN \'SHOES\' WHEN \'ACCESSORY\' THEN \'ACCESSORIES\' WHEN \'ACCESSORIES\' THEN \'ACCESSORIES\' WHEN \'SUNGLASS\' THEN \'SUNGLASSES\' WHEN \'SUNGLASSES\' THEN \'SUNGLASSES\' WHEN \'BELT\' THEN \'BELTS\' WHEN \'BELTS\' THEN \'BELTS\' WHEN \'PERFUME\' THEN \'PERFUMES\' WHEN \'PERFUMES\' THEN \'PERFUMES\' WHEN \'FRAGRANCE\' THEN \'PERFUMES\' WHEN \'FRAGRANCES\' THEN \'PERFUMES\' WHEN \'PYJAMA\' THEN \'PYJAMAS\' WHEN \'PYJAMAS\' THEN \'PYJAMAS\' WHEN \'PAJAMA\' THEN \'PYJAMAS\' WHEN \'PAJAMAS\' THEN \'PYJAMAS\' WHEN \'LUGGAGE\' THEN \'LUGGAGE\' WHEN \'TROLLY\' THEN \'LUGGAGE\' WHEN \'TROLLIES\' THEN \'LUGGAGE\' WHEN \'SUITCASE\' THEN \'LUGGAGE\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END ) AS CATEGORY, COALESCE(META.STYLE, \'SNITCH\') AS STYLE, COALESCE(META.META1, \'NA\') AS META1, COALESCE(META.META2, \'NA\') AS META2, COALESCE(META.META3, \'NA\') AS META3, COALESCE( R_EXACT.PRICE_SLAB_CODE, R_CAT.PRICE_SLAB_CODE, R_FALLBACK.PRICE_SLAB_CODE, CONCAT(\'SLAB_\', GREATEST(1, LEAST(10, FLOOR(COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) / 200) - 3))) ) AS PRICE_SLAB_CODE, COALESCE( R_EXACT.PRICE_RANGE_LABEL, R_CAT.PRICE_RANGE_LABEL, R_FALLBACK.PRICE_RANGE_LABEL, CONCAT(\'₹\', (FLOOR(COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) / 200) * 200), \' – ₹\', (FLOOR(COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) / 200) * 200) + 199) ) AS PRICE_RANGE_LABEL, COALESCE(I.INVENTORY, 0) AS INV_UNITS_OPENING_CALENDAR_INSTORE, COALESCE(I.JIT_QTY, 0) AS INV_UNITS_OPENING_CALENDAR_JIT, (COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_OPENING_CALENDAR FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.OPENING_DATE_CALENDAR LEFT JOIN SKU_META_MASTER META ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = META.CLEAN_SKU_GROUP LEFT JOIN SKU_LIVE_MRP P ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = P.CLEAN_SKU_GROUP LEFT JOIN META_AVG_PRICES MA ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), MA.CATEGORY) AND EQUAL_NULL(COALESCE(META.STYLE, \'SNITCH\'), MA.STYLE) AND EQUAL_NULL(COALESCE(META.META1, \'NA\'), MA.META1) AND EQUAL_NULL(COALESCE(META.META2, \'NA\'), MA.META2) AND EQUAL_NULL(COALESCE(META.META3, \'NA\'), MA.META3) LEFT JOIN CATEGORY_AVG_PRICES CA ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), CA.CATEGORY) LEFT JOIN REF_SLABS_EXACT R_EXACT ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), R_EXACT.CATEGORY) AND EQUAL_NULL(COALESCE(META.STYLE, \'SNITCH\'), R_EXACT.STYLE) AND EQUAL_NULL(COALESCE(META.META1, \'NA\'), R_EXACT.META1) AND EQUAL_NULL(COALESCE(META.META2, \'NA\'), R_EXACT.META2) AND EQUAL_NULL(COALESCE(META.META3, \'NA\'), R_EXACT.META3) AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R_EXACT.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R_EXACT.SLAB_MAX_PRICE LEFT JOIN REF_SLABS_CAT_ONLY R_CAT ON EQUAL_NULL(COALESCE(META.CATEGORY, \'OTHERS\'), R_CAT.CATEGORY) AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R_CAT.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R_CAT.SLAB_MAX_PRICE LEFT JOIN FALLBACK_PRICE_SLABS R_FALLBACK ON COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R_FALLBACK.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R_FALLBACK.SLAB_MAX_PRICE LEFT JOIN STORE_ZONE_MAP_CLEAN M ON CAST(I.BRANCH_CODE AS VARCHAR) = M.BRANCH_CODE WHERE I.DATE >= \'2026-04-01\' AND CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') AND UPPER(TRIM(I.SKU_GROUP)) NOT LIKE \'CB%\' AND UPPER(TRIM(I.SKU_GROUP)) NOT LIKE \'NT%\' ), OPENING_INV_30 AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'OTH